#!/usr/bin/env python3
"""Traduzioni olandesi per i contenuti prodotto generati.

Perche' esiste: i moduli `product_content_*.py` costruiscono un dizionario
per-lingua per ogni campo di ogni SKU. Quando la chiave `nl` manca, sia
`L()` sia `backfill_lang()` la riempivano copiando l'inglese: il risultato
erano schede prodotto olandesi con la copy specifica del prodotto (eyebrow,
desc, feature, keypoint, spec, FAQ, SEO title/description) ancora in inglese.

Invece di aggiungere `nl=...` a mano in centinaia di call site sparse su nove
moduli, la traduzione vive qui in un unico posto: una mappa
`stringa inglese -> stringa olandese`. `nl_text()` la consulta e, se la voce
manca, restituisce l'inglese invariato (stesso comportamento di prima, quindi
il generatore non esplode mai per una stringa nuova non ancora tradotta).

Le chiavi sono le stringhe inglesi *sorgente*, HTML inline compreso: vanno
copiate esattamente come stanno nei moduli, entita' (`&amp;`, `&#x27;`) e
tipografia (’ — ·) incluse, altrimenti il lookup non fa match.

Per trovare cosa manca ancora:
    python scripts/check-nl-translations.py
"""

import re as _re

NL: dict[str, str] = {}

# Stringhe passate a `nl_text` senza una voce in NL: restituite in inglese.
# `scripts/check-nl-translations.py` le legge dopo aver importato i moduli di
# contenuto, cosi' il controllo copre *ogni* percorso che passa di qui, non
# solo `L()` e `backfill_lang()`.
MISSING: set[str] = set()

# Stringhe che in olandese restano identiche all'inglese di proposito (nomi di
# prodotto, sigle, unita'): elencate qui per non ricomparire come "da tradurre".
SAME_AS_EN: set[str] = set()


_TAG_RE = _re.compile(r"<[^>]+>")
_ASSET_RE = _re.compile(r"^\.{0,2}[\w\-./]+\.(?:webp|png|jpe?g|svg|gif|avif)$", _re.I)


def _is_translatable(text):
    """Falso per i valori che passano di qui ma non sono prosa da tradurre.

    Sono soprattutto costanti tecniche che i moduli tengono nelle stesse
    strutture per-lingua dei testi: markup di icone SVG (nessun nodo di testo),
    path di asset, token di colore/slug. Escluderli qui evita di doverli
    elencare a uno a uno in SAME_AS_EN e tiene pulito l'output del checker.
    """
    if _ASSET_RE.match(text):
        return False
    return bool(_re.search(r"[A-Za-z]", _TAG_RE.sub("", text)))


def nl_text(en):
    """Traduzione olandese di `en`; l'inglese invariato se non e' mappata.

    Accetta anche liste/tuple/dict per-campo (i moduli passano liste di
    feature o dizionari di righe spec) e le traduce ricorsivamente.
    """
    if isinstance(en, str):
        if (
            en not in NL
            and en.strip()
            and en not in SAME_AS_EN
            and _is_translatable(en)
        ):
            MISSING.add(en)
        return NL.get(en, en)
    if isinstance(en, list):
        return [nl_text(v) for v in en]
    if isinstance(en, tuple):
        return tuple(nl_text(v) for v in en)
    if isinstance(en, dict):
        return {k: nl_text(v) for k, v in en.items()}
    return en


